insert into public.projects (id, created_by, is_sample, title, short_description, summary, key_results, methodology, institution, area, type, status, project_date, period, tags, visual_type, media_url, images, favorites_base, created_at) values
('91dd2365-3814-4314-b6e6-336d8260b6b9', '2fac2abc-9a3b-46e4-a1e3-b464672e5edb', true, 'Calçada Acessível: detecção de obstáculos em calçadas com visão computacional', 'Modelo de visão computacional que identifica buracos, rampas e obstáculos em fotos de calçadas para mapear rotas acessíveis.', 'O projeto treina um detector de objetos com fotos de calçadas de Niterói enviadas por voluntários. Cada detecção vira um ponto num mapa colaborativo que mostra quais trechos são seguros para cadeirantes e pessoas com deficiência visual. A prefeitura recebeu o primeiro relatório com 3 bairros mapeados.', array['Precisão média na detecção de obstáculos: 87%', 'Trechos de calçada mapeados: 42 km', 'Voluntários enviando fotos: 130']::text[], 'Coleta colaborativa de 6 mil fotos com aplicativo próprio; rotulagem em Label Studio; treino de YOLOv8 com aumento de dados; validação cruzada por bairro; publicação dos resultados em mapa web com Leaflet.', 'UFF', 'Visão Computacional', 'Iniciação Científica', 'Em andamento', '2026-03-10', 'mar. 2026 - atual', array['Visão Computacional', 'Python', 'PyTorch', 'Acessibilidade', 'Mapas']::text[], 'standard', 'https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1483729558449-99ef09a8c325?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1580894894513-541e068a3e2b?w=1200&auto=format&fit=crop&q=80']::text[], 64, timestamp '2026-03-10 12:00'),
('a5a6f7c9-0e2e-4e0a-a14f-d52bbb1140f1', '2fac2abc-9a3b-46e4-a1e3-b464672e5edb', true, 'Redesign do aplicativo de matrícula da universidade', 'Pesquisa com 200 estudantes e novo protótipo do fluxo de matrícula, testado com usuários reais do campus.', 'A matrícula online era a maior fonte de reclamações no centro acadêmico. Conduzimos entrevistas, mapeamos a jornada e redesenhamos o fluxo de escolha de disciplinas. O protótipo final reduziu pela metade o tempo para montar a grade em testes de usabilidade.', array['Tempo para montar a grade: -52%', 'Satisfação no teste de usabilidade: 4,6/5']::text[], 'Pesquisa qualitativa com entrevistas semiestruturadas; questionário com 200 respostas; mapa de jornada; protótipo navegável em Figma; dois ciclos de teste de usabilidade com 12 participantes.', 'UFF', 'Design', 'Projeto de disciplina', 'Concluído', '2025-12-12', 'ago. 2025 - dez. 2025', array['Figma', 'UX Research', 'Design', 'Prototipagem']::text[], 'standard', 'https://images.unsplash.com/photo-1559028012-481c04fa702d?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1559028012-481c04fa702d?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1552664730-d307ca884978?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1543269865-cbf427effbad?w=1200&auto=format&fit=crop&q=80']::text[], 38, timestamp '2025-12-12 12:00'),
('e635a45e-0413-4f28-9129-905a6cf1ff01', '2fac2abc-9a3b-46e4-a1e3-b464672e5edb', true, 'Guia do campus em realidade aumentada', 'Aplicativo que mostra, pela câmera do celular, salas, laboratórios e horários de atendimento no campus do Gragoatá.', 'Calouros se perdem no campus nas primeiras semanas. O aplicativo reconhece fachadas dos prédios e sobrepõe informações úteis, como salas, laboratórios e horários de monitoria. Foi usado na semana de recepção de calouros de 2026.', array['Calouros que usaram na recepção: 340', 'Prédios reconhecidos: 14']::text[], 'Reconhecimento de imagem com ARCore; base de dados de salas em Firebase; testes de campo com calouros; ajustes de iluminação para uso noturno.', 'UFF', 'Engenharia de Software', 'Projeto Prático', 'Concluído', '2026-03-28', 'jan. 2026 - mar. 2026', array['Kotlin', 'Realidade Aumentada', 'Mobile', 'Firebase']::text[], 'standard', 'https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1562774053-701939374585?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1593508512255-86ab42a8e620?w=1200&auto=format&fit=crop&q=80']::text[], 51, timestamp '2026-03-28 12:00'),
('d2bd89e0-bb79-46c7-a7fc-e31ad55bdb57', '172a49ad-6666-456e-bc8e-1b53a0ac8d82', true, 'Microrrede solar para escolas rurais do interior fluminense', 'Projeto e instalação de uma microrrede fotovoltaica com baterias e monitoramento remoto em uma escola rural.', 'A escola sofria com quedas de energia que interrompiam aulas e estragavam merenda. Projetamos uma microrrede com painéis, baterias e um controlador próprio que envia dados pela rede celular. Hoje a escola tem energia estável mesmo em dias de tempestade.', array['Horas sem energia por mês: de 31 para 2', 'Economia na conta de luz: 68%', 'Custo do controlador: R$ 410']::text[], 'Levantamento de carga; dimensionamento com PVsyst; controlador com ESP32 e telemetria LoRa; instalação em mutirão com a comunidade; monitoramento por 6 meses.', 'UFRJ', 'Engenharia Elétrica e Eletrônica', 'Projeto de Extensão', 'Concluído', '2025-10-20', 'fev. 2025 - out. 2025', array['Energia Solar', 'Sistemas Embarcados', 'ESP32', 'Sustentabilidade']::text[], 'standard', 'https://images.unsplash.com/photo-1509391366360-2e959784a276?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1509391366360-2e959784a276?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497435334941-8c899ee9e8e9?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1473341304170-971dccb5ac1e?w=1200&auto=format&fit=crop&q=80']::text[], 92, timestamp '2025-10-20 12:00'),
('bda20212-a9a6-4108-8ab2-b4df9bc20e0e', '289474a5-0c3e-45d4-acbf-1836132b55c8', true, 'Genômica de abelhas sem ferrão na Mata Atlântica', 'Sequenciamento e análise de diversidade genética de colônias de jataí em fragmentos de mata.', 'Coletamos amostras de 60 colônias de abelhas jataí em fragmentos de Mata Atlântica com diferentes graus de isolamento. A análise mostra perda de diversidade genética nos fragmentos menores, o que orienta a criação de corredores ecológicos.', array['Colônias sequenciadas: 60', 'Marcadores genéticos analisados: 12 mil']::text[], 'Coleta em campo; extração de DNA; sequenciamento ddRAD; pipeline em Snakemake; análises populacionais em R (adegenet, hierfstat).', 'USP', 'Bioinformática', 'Dissertação', 'Em andamento', '2025-11-02', 'mar. 2025 - atual', array['Bioinformática', 'Genômica', 'R', 'Biodiversidade']::text[], 'standard', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1532187863486-abf9dbad1b69?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1576086213369-97a306d36557?w=1200&auto=format&fit=crop&q=80']::text[], 47, timestamp '2025-11-02 12:00'),
('b5185655-111c-4493-ba6c-82b49057ed40', '57754daa-a64c-44ab-8d95-5efcce993eff', true, 'Robô autônomo para monitoramento de lavouras', 'Robô terrestre que percorre linhas de plantio e mapeia a saúde das plantas com câmera multiespectral.', 'Construímos um robô de baixo custo que navega entre linhas de cultivo usando GPS RTK e câmera. Ele gera mapas de vigor das plantas que ajudam pequenos produtores a aplicar insumos só onde é preciso.', array['Área monitorada por hora: 1,2 ha', 'Redução no uso de defensivos: 30%']::text[], 'Chassi em alumínio com motores de passo; ROS 2 com Nav2; GPS RTK; câmera multiespectral; testes em fazenda experimental da universidade.', 'UNICAMP', 'Robótica', 'Projeto de Engenharia', 'Em andamento', '2026-02-14', 'abr. 2025 - atual', array['ROS', 'Robótica', 'C++', 'Agricultura de Precisão']::text[], 'standard', 'https://images.unsplash.com/photo-1485827404703-89b55fcc595e?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1485827404703-89b55fcc595e?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1561144257-e32e8efc6c4f?w=1200&auto=format&fit=crop&q=80']::text[], 81, timestamp '2026-02-14 12:00'),
('a3aa8646-2e31-4024-8c72-3b0f9ea8152d', 'c6dc2a1d-5e6b-4304-8b8a-dc9cee4efc11', true, 'Mapa de segurança urbana para mulheres em Belo Horizonte', 'Cruzamento de dados abertos de iluminação, ocorrências e uso do solo para propor intervenções em praças.', 'Combinamos dados de iluminação pública, ocorrências registradas e entrevistas com moradoras para identificar trechos críticos. O resultado é um caderno de propostas de desenho urbano entregue à secretaria de planejamento.', array['Pontos críticos mapeados: 118', 'Entrevistas realizadas: 64']::text[], 'Dados abertos da prefeitura; análise espacial em QGIS; oficinas participativas; propostas de projeto em Rhino.', 'UFMG', 'Arquitetura e Urbanismo', 'Trabalho de Conclusão de Curso', 'Em andamento', '2026-01-20', 'ago. 2025 - atual', array['QGIS', 'Urbanismo', 'Dados Abertos', 'Mobilidade']::text[], 'standard', 'https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1508385082359-f38ae991e8f2?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1528605248644-14dd04022da1?w=1200&auto=format&fit=crop&q=80']::text[], 59, timestamp '2026-01-20 12:00'),
('ab428a53-7949-434a-ba83-d09511ba13b6', '94cbc1f9-eb7b-46e9-89e5-59353263f6cb', true, 'Classificação automática de propostas legislativas', 'Modelo de linguagem que classifica projetos de lei por tema e mede a similaridade entre propostas.', 'Analisamos 40 mil projetos de lei da Câmara para entender quais temas crescem a cada legislatura. O modelo também encontra propostas quase idênticas apresentadas por diferentes parlamentares.', array['Projetos de lei analisados: 40 mil', 'F1 na classificação por tema: 0,91']::text[], 'Coleta pela API de dados abertos; pré-processamento com spaCy; ajuste fino de BERTimbau; análise de similaridade com embeddings.', 'UnB', 'Inteligência Artificial', 'Tese', 'Em andamento', '2025-09-15', 'mar. 2024 - atual', array['NLP', 'Python', 'Políticas Públicas', 'BERT']::text[], 'standard', 'https://images.unsplash.com/photo-1507842217343-583bb7270b66?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1507842217343-583bb7270b66?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1515879218367-8466d910aaa4?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=1200&auto=format&fit=crop&q=80']::text[], 103, timestamp '2025-09-15 12:00'),
('90c1610f-e61b-4360-b0c6-aad6f7f5f1ed', 'd9494093-240c-4b13-b115-28271d63f1aa', true, 'Leitor de cardápios para pessoas com deficiência visual', 'Aplicativo que lê cardápios fotografados em voz alta e organiza os itens por categoria e preço.', 'Pessoas cegas relataram dificuldade para pedir em restaurantes sem cardápio acessível. O aplicativo reconhece o texto, separa pratos, preços e categorias e permite navegar por voz.', array['Participantes nos testes: 18', 'Acerto na leitura de preços: 96%']::text[], 'Entrevistas com usuários; OCR com ML Kit; navegação por voz; testes com o laboratório de tecnologia assistiva.', 'UFPE', 'Design', 'Projeto de Extensão', 'Concluído', '2025-11-28', 'mar. 2025 - nov. 2025', array['Acessibilidade', 'UX Research', 'Mobile', 'OCR']::text[], 'standard', 'https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1559028012-481c04fa702d?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1491438590914-bc09fcaaf77a?w=1200&auto=format&fit=crop&q=80']::text[], 77, timestamp '2025-11-28 12:00'),
('9daf121b-21ba-4cd6-8f4f-fbde3f024fbf', '18e94949-9ebf-44f6-8059-f8cd53407257', true, 'Detecção de intrusão em redes universitárias com aprendizado de máquina', 'Sistema que analisa tráfego de rede do campus e alerta sobre comportamentos suspeitos em tempo real.', 'Treinamos modelos com tráfego anonimizado da rede do campus para identificar varreduras e ataques de força bruta. O protótipo já roda em paralelo ao firewall do instituto.', array['Ataques detectados no piloto: 1.240', 'Falsos positivos: 2,1%']::text[], 'Captura com Zeek; engenharia de atributos; modelos de floresta aleatória e autoencoders; painel em Grafana.', 'UFRGS', 'Redes e Segurança', 'Iniciação Científica', 'Em andamento', '2026-01-08', 'jun. 2025 - atual', array['Segurança', 'Redes', 'Machine Learning', 'Linux']::text[], 'standard', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544197150-b99a580bb7a8?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1573164713988-8665fc963095?w=1200&auto=format&fit=crop&q=80']::text[], 69, timestamp '2026-01-08 12:00'),
('cd6bf8a2-4117-4b1b-8390-5c0c453c3188', 'a9c3bf98-3471-46b2-9885-1c4686939cd6', true, 'Compósitos impressos em 3D com fibra de bananeira', 'Filamento de impressão 3D reforçado com fibra de bananeira para peças leves e resistentes.', 'Testamos misturas de PLA com fibra de bananeira tratada e comparamos resistência e peso com o PLA puro. As peças foram usadas no protótipo do carro Baja da equipe.', array['Ganho de rigidez: 22%', 'Redução de massa da peça: 9%']::text[], 'Tratamento alcalino da fibra; extrusão do filamento; impressão de corpos de prova; ensaios de tração e flexão.', 'UFSC', 'Engenharia Mecânica', 'Iniciação Científica', 'Concluído', '2025-09-30', 'mar. 2025 - set. 2025', array['Impressão 3D', 'Materiais', 'SolidWorks', 'Sustentabilidade']::text[], 'standard', 'https://images.unsplash.com/photo-1559136555-9303baea8ebd?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1559136555-9303baea8ebd?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1581092160562-40aa08e78837?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=1200&auto=format&fit=crop&q=80']::text[], 44, timestamp '2025-09-30 12:00'),
('736ea0c7-8c24-4df6-858f-0c4df36743ec', '9957057d-3356-4b77-903f-cef8a023c985', true, 'Aplicativo de pedidos para comércios de bairro', 'App gratuito para pequenos comércios receberem pedidos pelo celular sem pagar taxas de plataforma.', 'Comerciantes da zona norte pagavam até 27% de taxa para aplicativos de entrega. Desenvolvemos um app simples em que o próprio comércio publica o cardápio e recebe pedidos por mensagem.', array['Comércios usando o app: 23', 'Pedidos por mês: 1.800']::text[], 'Entrevistas com comerciantes; desenvolvimento em Flutter; backend em Firebase; acompanhamento semanal com os usuários.', 'CEFET/RJ', 'Engenharia de Software', 'Projeto de Extensão', 'Em andamento', '2026-02-02', 'jul. 2025 - atual', array['Flutter', 'Mobile', 'Firebase', 'Empreendedorismo']::text[], 'standard', 'https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1563986768609-322da13575f3?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1556761175-b413da4baf72?w=1200&auto=format&fit=crop&q=80']::text[], 58, timestamp '2026-02-02 12:00'),
('4b6fdc20-6a4f-478d-b9ba-a9c01d73dc09', '2636a1ce-1aa9-45f5-983e-4396fbcf7d42', true, 'Triagem de risco cardiovascular na atenção primária', 'Ferramenta de apoio à decisão que estima risco cardiovascular a partir de dados de prontuário.', 'Agentes de saúde não tinham uma forma rápida de priorizar visitas. O painel estima o risco de cada paciente a partir de dados do prontuário e sugere quem deve ser visitado primeiro.', array['Pacientes avaliados no piloto: 2.300', 'Sensibilidade para alto risco: 0,88']::text[], 'Base anonimizada de prontuários; modelo de regressão logística calibrado; painel em Shiny; avaliação com equipe de saúde da família.', 'UERJ', 'Saúde', 'Iniciação Científica', 'Em andamento', '2025-12-03', 'abr. 2025 - atual', array['Saúde Digital', 'R', 'Epidemiologia', 'Saúde Pública']::text[], 'standard', 'https://images.unsplash.com/photo-1576091160550-2173dba999ef?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1576091160550-2173dba999ef?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1530026405186-ed1f139313f8?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=1200&auto=format&fit=crop&q=80']::text[], 66, timestamp '2025-12-03 12:00'),
('8c65d7e8-03c9-4bd0-94ad-3602c69f4ba4', '51fb2caf-babc-44fb-9356-9eda8b35cbff', true, 'Concreto com resíduos de construção para habitação social', 'Dosagem de concreto com agregado reciclado e avaliação de custo para casas populares.', 'Substituímos parte da brita por agregado reciclado de demolições e avaliamos resistência e custo. A mistura final atende às normas para blocos de vedação e reduz o custo em 18%.', array['Redução de custo do bloco: 18%', 'Resíduo reaproveitado por m³: 420 kg']::text[], 'Caracterização dos agregados; dosagem experimental; ensaios de compressão; modelagem BIM de uma casa protótipo.', 'PUC-Rio', 'Engenharia Civil', 'Trabalho de Conclusão de Curso', 'Concluído', '2025-12-15', 'fev. 2025 - dez. 2025', array['Engenharia Civil', 'BIM', 'Sustentabilidade', 'Concreto']::text[], 'standard', 'https://images.unsplash.com/photo-1581092160562-40aa08e78837?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1581092160562-40aa08e78837?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1528605248644-14dd04022da1?w=1200&auto=format&fit=crop&q=80']::text[], 41, timestamp '2025-12-15 12:00'),
('4a6bcdd3-3e90-4f94-b774-80567983387e', 'a7a9e886-eb75-4538-a10f-d9e9bc140d6e', true, 'Educação financeira gamificada para o ensino médio', 'Jogo de celular que ensina orçamento e juros para estudantes de escolas públicas.', 'Criamos um jogo em que o estudante administra a renda de uma família fictícia por 12 meses. Aplicado em 4 escolas, o jogo melhorou o desempenho em um teste de conhecimentos financeiros.', array['Estudantes participantes: 480', 'Melhora no teste de conhecimentos: +34%']::text[], 'Pesquisa com professores; design de jogo; desenvolvimento em Unity; aplicação em sala com pré e pós-teste.', 'Ibmec', 'Educação', 'Projeto de Extensão', 'Concluído', '2025-11-20', 'mar. 2025 - nov. 2025', array['Educação', 'Empreendedorismo', 'Gamificação']::text[], 'standard', 'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1522202176988-66273c2fd55f?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=1200&auto=format&fit=crop&q=80']::text[], 72, timestamp '2025-11-20 12:00'),
('518bc18f-6f0f-4859-9f0f-8545443f7b15', '068d5593-06cd-4879-92af-15ce47ca44cc', true, 'Simulação de plasmas de baixa temperatura em GPU', 'Código de partículas em GPU que acelera em 40 vezes simulações de descargas elétricas em gases.', 'Reescrevemos um código de simulação de plasma para rodar em GPU. O ganho de velocidade permitiu estudar regimes antes inviáveis, com aplicações em tratamento de superfícies.', array['Aceleração em relação à CPU: 40x', 'Partículas simuladas: 200 milhões']::text[], 'Método particle-in-cell; implementação em Julia com CUDA.jl; validação com resultados experimentais; execução no cluster da universidade.', 'UFF', 'Ciência de Dados', 'Dissertação', 'Em andamento', '2025-10-05', 'mar. 2025 - atual', array['Julia', 'HPC', 'Física', 'Simulação']::text[], 'standard', 'https://images.unsplash.com/photo-1507413245164-6160d8298b31?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1507413245164-6160d8298b31?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1564325724739-bae0bd08762c?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1580894894513-541e068a3e2b?w=1200&auto=format&fit=crop&q=80']::text[], 39, timestamp '2025-10-05 12:00'),
('bbe03ece-79bf-43bc-8d3a-f72fb1d5582c', '83542116-501c-4021-86e8-650404dbb0eb', true, 'Monitoramento da Baía de Guanabara por satélite', 'Série histórica de turbidez e clorofila da baía estimada com imagens Sentinel-2 e validada com sensores.', 'Montamos uma série de cinco anos de qualidade da água da Baía de Guanabara a partir de imagens de satélite. Sensores de baixo custo instalados com pescadores validam as estimativas.', array['Imagens processadas: 1.900', 'Erro médio na turbidez: 11%']::text[], 'Google Earth Engine; correção atmosférica; modelos de regressão com dados de campo; boias com sensores de baixo custo.', 'UFRJ', 'Sustentabilidade', 'Iniciação Científica', 'Em andamento', '2026-02-20', 'ago. 2025 - atual', array['Sensoriamento Remoto', 'Google Earth Engine', 'Python', 'Hidrologia']::text[], 'standard', 'https://images.unsplash.com/photo-1483729558449-99ef09a8c325?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1483729558449-99ef09a8c325?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544989164-31dc3c645987?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=1200&auto=format&fit=crop&q=80']::text[], 84, timestamp '2026-02-20 12:00'),
('833fe809-2030-4d1e-ba64-7b4c485ed912', '1d32a14e-bbef-468b-8a47-da3bfa92f222', true, 'Roteirização da coleta seletiva em cidades médias', 'Modelo de otimização que redesenha as rotas de caminhões de coleta seletiva e reduz quilômetros rodados.', 'Com dados de pontos de coleta de uma cidade de 200 mil habitantes, otimizamos as rotas dos caminhões. A proposta reduz a distância percorrida e permite atender bairros hoje sem coleta.', array['Redução da distância percorrida: 23%', 'Novos bairros atendidos: 6']::text[], 'Modelagem como problema de roteamento com janelas de tempo; resolução com Gurobi e heurísticas; validação com motoristas.', 'UFMG', 'Dados e Análise', 'Iniciação Científica', 'Concluído', '2025-10-30', 'mar. 2025 - out. 2025', array['Otimização', 'Python', 'Pesquisa Operacional', 'Sustentabilidade']::text[], 'standard', 'https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1200&auto=format&fit=crop&q=80']::text[], 33, timestamp '2025-10-30 12:00'),
('8bd284f4-b57e-4636-9207-9d27aa0e2b9a', '90966322-bba1-4400-b809-1b16905ae78a', true, 'Corpus de português falado nas periferias de São Paulo', 'Coleta e transcrição de 120 horas de fala para treinar reconhecedores de voz mais inclusivos.', 'Reconhecedores de voz erram mais com sotaques periféricos. Gravamos e transcrevemos conversas com consentimento de moradores e mostramos que o ajuste fino com esse corpus reduz bastante os erros.', array['Horas de fala transcritas: 120', 'Redução da taxa de erro de palavras: 37%']::text[], 'Gravações em oficinas comunitárias; transcrição com revisão dupla; ajuste fino de Whisper; avaliação por região.', 'USP', 'Inteligência Artificial', 'Iniciação Científica', 'Em andamento', '2025-12-18', 'fev. 2025 - atual', array['NLP', 'Linguística', 'Python', 'Reconhecimento de Fala']::text[], 'standard', 'https://images.unsplash.com/photo-1475721027785-f74eccf877e2?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1475721027785-f74eccf877e2?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1529070538774-1843cb3265df?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1491438590914-bc09fcaaf77a?w=1200&auto=format&fit=crop&q=80']::text[], 61, timestamp '2025-12-18 12:00'),
('7560c75c-c48f-49f9-b92d-3ec5a1f9a337', '8ce2c943-6f2c-4ec8-830c-9c2a135042c0', true, 'Software de voo para CubeSat universitário', 'Sistema embarcado que controla energia, comunicação e câmera de um nanossatélite de 1U.', 'O CubeSat da UnB precisava de um software de voo confiável. Escrevemos o sistema que gerencia energia, telemetria e a câmera, testado em câmara térmica e em voo de balão estratosférico.', array['Altitude no voo de balão: 31 km', 'Pacotes de telemetria recebidos: 98%']::text[], 'FreeRTOS em microcontrolador ARM; testes em hardware-in-the-loop; câmara térmica; voo de balão com recuperação.', 'UnB', 'Engenharia Elétrica e Eletrônica', 'Projeto de Engenharia', 'Em andamento', '2026-01-30', 'mar. 2024 - atual', array['Sistemas Embarcados', 'C', 'Aeroespacial', 'Telemetria']::text[], 'standard', 'https://images.unsplash.com/photo-1507413245164-6160d8298b31?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1507413245164-6160d8298b31?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1581092918056-0c4c3acd3789?w=1200&auto=format&fit=crop&q=80']::text[], 112, timestamp '2026-01-30 12:00'),
('329dd6e8-4ba6-4b16-947f-65596394fcee', '47934575-4f47-4fc8-b053-6fcdb2264f02', true, 'Explicações de decisões de crédito para pessoas leigas', 'Estudo com usuários sobre como explicar decisões de modelos de crédito de forma justa e compreensível.', 'Testamos quatro formatos de explicação de decisões de crédito com 300 participantes. Explicações contrafactuais curtas foram as mais compreendidas e as que mais aumentaram a confiança.', array['Participantes do estudo: 300', 'Compreensão com explicação contrafactual: 81%']::text[], 'Modelos de crédito treinados em base pública; geração de explicações SHAP e contrafactuais; experimento online entre sujeitos.', 'UFSC', 'Inteligência Artificial', 'Tese', 'Em andamento', '2025-08-22', 'mar. 2023 - atual', array['Ética em IA', 'Machine Learning', 'Fairness', 'Python']::text[], 'standard', 'https://images.unsplash.com/photo-1515879218367-8466d910aaa4?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1515879218367-8466d910aaa4?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=1200&auto=format&fit=crop&q=80']::text[], 95, timestamp '2025-08-22 12:00'),
('3a51af2d-54f2-4355-8ebb-5b5e48fa06fd', '94a14572-afcd-4027-b9fa-7049195a5982', true, 'Prótese de mão mioelétrica de baixo custo', 'Prótese impressa em 3D controlada por sinais musculares, custando menos de 5% de uma prótese comercial.', 'Em parceria com um centro de reabilitação, desenvolvemos uma prótese de mão impressa em 3D que abre e fecha com sinais dos músculos do antebraço. Três pacientes testaram o protótipo por um mês.', array['Custo de materiais: R$ 780', 'Movimentos reconhecidos: 4', 'Pacientes no teste: 3']::text[], 'Captação de sinais EMG; classificação com Arduino; projeto mecânico em Fusion 360; impressão em PETG; testes de uso com terapeutas.', 'UFPE', 'Saúde', 'Projeto de Engenharia', 'Em andamento', '2026-03-02', 'fev. 2025 - atual', array['Engenharia Biomédica', 'Impressão 3D', 'Arduino', 'Sinais Biológicos']::text[], 'standard', 'https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1559136555-9303baea8ebd?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1581092918056-0c4c3acd3789?w=1200&auto=format&fit=crop&q=80']::text[], 128, timestamp '2026-03-02 12:00'),
('ab352e9f-709a-420a-a6c0-4b73fa069d9c', 'c0a36741-1e20-407e-b205-53aa6bb1c037', true, 'Detecção de pragas em arrozais com drones', 'Imagens de drone e um classificador leve identificam focos de pragas em lavouras familiares.', 'Pequenos produtores de arroz perdem parte da safra porque descobrem pragas tarde. Voos semanais com drone e um classificador que roda no celular mostram os focos no mapa da propriedade.', array['Propriedades atendidas: 11', 'Acurácia na detecção de pragas: 89%']::text[], 'Voos com drone de baixo custo; ortomosaicos em OpenDroneMap; classificador MobileNet; aplicativo offline para o produtor.', 'UFRGS', 'Visão Computacional', 'Trabalho de Conclusão de Curso', 'Em andamento', '2026-02-26', 'ago. 2025 - atual', array['Drones', 'Visão Computacional', 'Agronomia', 'Python']::text[], 'standard', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1464226184884-fa280b87c399?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1416879595882-3373a0480b5b?w=1200&auto=format&fit=crop&q=80']::text[], 49, timestamp '2026-02-26 12:00'),
('7f579224-afba-462f-ad9d-373fc8b90740', 'b0366af0-b5c5-43b8-a5cd-f699a49fbca5', true, 'Kit de sensores abertos para hackathons de cidade inteligente', 'Placas, firmware e tutoriais para equipes montarem sensores urbanos em um fim de semana.', 'Nos hackathons, as equipes perdiam metade do tempo montando hardware. O kit traz placas prontas, firmware e tutoriais, e já foi usado por 40 equipes em três eventos.', array['Equipes que usaram o kit: 40', 'Tempo médio de montagem: 25 min']::text[], 'Placa própria com ESP32; firmware em MicroPython; documentação aberta; oficinas antes dos eventos.', 'UNICAMP', 'Engenharia Elétrica e Eletrônica', 'Projeto de Extensão', 'Concluído', '2025-08-30', 'jan. 2025 - ago. 2025', array['ESP32', 'Sistemas Embarcados', 'Cidades Inteligentes', 'Python']::text[], 'standard', 'https://images.unsplash.com/photo-1576267423445-b2e0074d68a4?w=1200&auto=format&fit=crop&q=80', array['https://images.unsplash.com/photo-1576267423445-b2e0074d68a4?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=1200&auto=format&fit=crop&q=80']::text[], 57, timestamp '2025-08-30 12:00')
