insert into public.events (id, is_sample, title, category, status, starts_at, ends_at, location, city, organizer, modality, tags, short_description, about_text, speakers, schedule, attendees_base, cover_url) values
('7071b30e-d7ab-4133-b67d-ffed472e1ce9', true, 'Hackathon Cidades Resilientes', 'Hackathon', 'Inscrições abertas', (timestamp '2026-11-28 09:00' at time zone 'America/Sao_Paulo'), (timestamp '2026-11-29 18:00' at time zone 'America/Sao_Paulo'),
  'Centro de Tecnologia da UFRJ', 'Rio de Janeiro', 'Liga Acadêmica de IA — UFRJ', 'Presencial', array['Dados Abertos', 'Cidades Inteligentes', 'Sustentabilidade']::text[], '36 horas para criar soluções com dados abertos para enchentes, calor e mobilidade no Rio.', 'Equipes de até cinco pessoas recebem bases de dados da cidade e mentoria de pesquisadores. Os três melhores projetos ganham incubação por seis meses.', '[{"id":"s1","name":"Natália Souza","role":"Mentora de dados ambientais","avatar":"https://randomuser.me/api/portraits/women/63.jpg"},{"id":"s2","name":"Gabriel Costa","role":"Mentor de geoprocessamento"}]'::jsonb, '[{"time":"09:00","title":"Abertura e formação de equipes"},{"time":"13:00","title":"Mentorias"},{"time":"16:00","title":"Apresentações finais"}]'::jsonb, 186, 'https://images.unsplash.com/photo-1576267423445-b2e0074d68a4?w=1200&auto=format&fit=crop&q=80'),
('85e94375-d8fe-4f4e-ad42-f52d72bf09a8', true, 'Semana de Inteligência Artificial da UFSC', 'Semana acadêmica', 'Inscrições abertas', (timestamp '2026-12-01 09:00' at time zone 'America/Sao_Paulo'), (timestamp '2026-12-05 18:00' at time zone 'America/Sao_Paulo'),
  'Auditório do CTC', 'Florianópolis', 'Universidade Federal de Santa Catarina (UFSC)', 'Híbrido', array['Inteligência Artificial', 'Ética em IA', 'Machine Learning']::text[], 'Cinco dias de palestras, minicursos e pôsteres sobre IA responsável e aplicações no Brasil.', 'A semana reúne pesquisadores, estudantes e empresas. Haverá minicursos de PyTorch, mesa sobre regulação de IA e sessão de pôsteres de iniciação científica.', '[{"id":"s1","name":"Marina Lopes","role":"Doutoranda em IA Responsável","avatar":"https://randomuser.me/api/portraits/women/8.jpg"},{"id":"s2","name":"Rodrigo Nascimento","role":"Pesquisador em NLP","avatar":"https://randomuser.me/api/portraits/men/75.jpg"}]'::jsonb, '[{"time":"09:00","title":"Abertura"},{"time":"10:30","title":"Minicurso de PyTorch"},{"time":"14:00","title":"Mesa: regulação de IA no Brasil"}]'::jsonb, 412, 'https://images.unsplash.com/photo-1519452635265-7b1fbfd1e4e0?w=1200&auto=format&fit=crop&q=80'),
('0b753185-8886-4384-8715-150aa7843f05', true, 'Torneio Universitário de Robótica Autônoma', 'Competição', 'Inscrições abertas', (timestamp '2026-12-12 08:00' at time zone 'America/Sao_Paulo'), (timestamp '2026-12-13 17:00' at time zone 'America/Sao_Paulo'),
  'Ginásio da UNICAMP', 'Campinas', 'Laboratório Hacker — UNICAMP', 'Presencial', array['Robótica', 'ROS', 'Visão Computacional']::text[], 'Equipes de todo o país disputam provas de navegação, manipulação e futebol de robôs.', 'O torneio tem três modalidades e uma sessão de demonstração aberta ao público. Equipes estreantes recebem mentoria técnica antes da competição.', '[{"id":"s1","name":"Pedro Henrique Lima","role":"Capitão da equipe anfitriã","avatar":"https://randomuser.me/api/portraits/men/46.jpg"},{"id":"s2","name":"Tiago Mendes","role":"Juiz técnico"}]'::jsonb, '[{"time":"08:00","title":"Credenciamento"},{"time":"10:00","title":"Provas de navegação"},{"time":"15:00","title":"Finais de futebol de robôs"}]'::jsonb, 254, 'https://images.unsplash.com/photo-1527430253228-e93688616381?w=1200&auto=format&fit=crop&q=80'),
('cd0896d8-5a96-4a86-83a0-bf1fafa780f3', true, 'Encontro de UX e Acessibilidade', 'Workshop', 'Inscrições abertas', (timestamp '2026-11-21 14:00' at time zone 'America/Sao_Paulo'), (timestamp '2026-11-21 18:00' at time zone 'America/Sao_Paulo'),
  'Centro de Artes e Comunicação da UFPE', 'Recife', 'Universidade Federal de Pernambuco (UFPE)', 'Presencial', array['UX Research', 'Acessibilidade', 'Design']::text[], 'Oficina prática de testes de usabilidade com pessoas com deficiência.', 'Os participantes planejam e conduzem um teste de usabilidade com acompanhamento de especialistas. Traga seu notebook e um protótipo, se tiver.', '[{"id":"s1","name":"Fernanda Ribeiro","role":"Designer e pesquisadora","avatar":"https://randomuser.me/api/portraits/women/31.jpg"}]'::jsonb, '[{"time":"14:00","title":"Boas-vindas"},{"time":"14:30","title":"Planejamento do teste"},{"time":"16:00","title":"Testes com participantes"}]'::jsonb, 64, 'https://images.unsplash.com/photo-1552664730-d307ca884978?w=1200&auto=format&fit=crop&q=80'),
('e79457de-1544-4595-a67f-91f02e6f07f4', true, 'Seminário de Transição Energética', 'Seminário', 'Inscrições abertas', (timestamp '2026-12-03 09:00' at time zone 'America/Sao_Paulo'), (timestamp '2026-12-03 17:00' at time zone 'America/Sao_Paulo'),
  'Online', 'Online', 'Universidade Federal do Rio de Janeiro (UFRJ)', 'Online', array['Energia Solar', 'Sustentabilidade', 'Engenharia Elétrica']::text[], 'Pesquisas sobre energia solar, eólica e microrredes em comunidades brasileiras.', 'Seminário online com apresentações de projetos de extensão e pesquisa em energia limpa, seguido de debate com gestores públicos.', '[{"id":"s1","name":"Lucas Ferreira","role":"Pesquisador em microrredes","avatar":"https://randomuser.me/api/portraits/men/32.jpg"}]'::jsonb, '[{"time":"09:00","title":"Abertura"},{"time":"10:00","title":"Painel: energia em comunidades isoladas"},{"time":"14:00","title":"Apresentações de projetos"}]'::jsonb, 338, 'https://images.unsplash.com/photo-1466611653911-95081537e5b7?w=1200&auto=format&fit=crop&q=80'),
('04cd64b1-9f88-4988-a06c-63be92e79192', true, 'Escola de Verão em Bioinformática', 'Curso', 'Inscrições abertas', (timestamp '2027-01-18 09:00' at time zone 'America/Sao_Paulo'), (timestamp '2027-01-22 17:00' at time zone 'America/Sao_Paulo'),
  'Instituto de Biociências da USP', 'São Paulo', 'Universidade de São Paulo (USP)', 'Presencial', array['Bioinformática', 'Genômica', 'R', 'Python']::text[], 'Uma semana de aulas práticas de análise genômica para estudantes de graduação.', 'Curso intensivo com aulas práticas em servidores da universidade: controle de qualidade, montagem de genomas e análises populacionais.', '[{"id":"s1","name":"Camila Rocha","role":"Monitora de genômica","avatar":"https://randomuser.me/api/portraits/women/68.jpg"},{"id":"s2","name":"Beatriz Vasconcelos","role":"Monitora de química computacional"}]'::jsonb, '[{"time":"09:00","title":"Linux para bioinformática"},{"time":"14:00","title":"Prática: controle de qualidade de leituras"}]'::jsonb, 80, 'https://images.unsplash.com/photo-1518152006812-edab29b069ac?w=1200&auto=format&fit=crop&q=80'),
('b29e721a-faf1-4a02-96a2-4d7fbb52c95f', true, 'CTF Universitário do Sul', 'Competição', 'Inscrições abertas', (timestamp '2026-11-29 10:00' at time zone 'America/Sao_Paulo'), (timestamp '2026-11-29 22:00' at time zone 'America/Sao_Paulo'),
  'Online', 'Online', 'Universidade Federal do Rio Grande do Sul (UFRGS)', 'Online', array['Segurança', 'Redes', 'Criptografia']::text[], 'Competição de segurança no formato capture the flag, aberta a estudantes de todo o Brasil.', 'Desafios de web, criptografia, engenharia reversa e forense. Equipes de até quatro pessoas. Haverá uma oficina introdutória na semana anterior.', '[{"id":"s1","name":"Gustavo Almeida","role":"Organizador","avatar":"https://randomuser.me/api/portraits/men/11.jpg"}]'::jsonb, '[{"time":"10:00","title":"Abertura dos desafios"},{"time":"22:00","title":"Encerramento e placar final"}]'::jsonb, 297, 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=1200&auto=format&fit=crop&q=80'),
('b4bed9a3-d853-42bf-be7c-c4d38809f385', true, 'Feira de Startups Universitárias', 'Feira', 'Inscrições abertas', (timestamp '2026-12-10 10:00' at time zone 'America/Sao_Paulo'), (timestamp '2026-12-10 19:00' at time zone 'America/Sao_Paulo'),
  'Campus Centro do Ibmec', 'Rio de Janeiro', 'Ibmec Rio', 'Presencial', array['Empreendedorismo', 'Inovação', 'Startups']::text[], 'Estudantes apresentam suas startups para investidores, aceleradoras e empresas.', 'Mais de 30 startups universitárias em estandes, rodada de pitches de 3 minutos e mentorias rápidas com investidores-anjo.', '[{"id":"s1","name":"Letícia Gomes","role":"Cofundadora de startup de educação financeira","avatar":"https://randomuser.me/api/portraits/women/22.jpg"},{"id":"s2","name":"Arthur","role":"Pesquisador em LLMs"}]'::jsonb, '[{"time":"10:00","title":"Abertura da feira"},{"time":"14:00","title":"Rodada de pitches"},{"time":"18:00","title":"Premiação"}]'::jsonb, 365, 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?w=1200&auto=format&fit=crop&q=80'),
('b0e1bfa3-dadd-4989-81b8-856c776f3c08', true, 'Jornada de Engenharia Aeroespacial', 'Palestra', 'Encerrado', (timestamp '2026-10-15 18:00' at time zone 'America/Sao_Paulo'), (timestamp '2026-10-15 21:00' at time zone 'America/Sao_Paulo'),
  'Auditório da Faculdade de Tecnologia da UnB', 'Brasília', 'Universidade de Brasília (UnB)', 'Híbrido', array['Aeroespacial', 'Sistemas Embarcados', 'CubeSats']::text[], 'Como estudantes brasileiros estão construindo satélites e foguetes na universidade.', 'Palestras sobre o projeto de CubeSat da UnB, voos de balão estratosférico e oportunidades de estágio no setor espacial.', '[{"id":"s1","name":"Henrique Araújo","role":"Engenheiro de software de voo","avatar":"https://randomuser.me/api/portraits/men/91.jpg"}]'::jsonb, '[{"time":"18:00","title":"Abertura"},{"time":"18:30","title":"O CubeSat da UnB"},{"time":"20:00","title":"Perguntas"}]'::jsonb, 221, 'https://images.unsplash.com/photo-1505373877841-8d25f7d46678?w=1200&auto=format&fit=crop&q=80'),
('64799a83-0d20-400a-8567-c0b5adf49bfe', true, 'Simpósio de Saúde Digital', 'Simpósio', 'Inscrições abertas', (timestamp '2027-02-05 09:00' at time zone 'America/Sao_Paulo'), (timestamp '2027-02-06 17:00' at time zone 'America/Sao_Paulo'),
  'Hospital Universitário Pedro Ernesto', 'Rio de Janeiro', 'Universidade do Estado do Rio de Janeiro (UERJ)', 'Presencial', array['Saúde Digital', 'Epidemiologia', 'Inteligência Artificial']::text[], 'Dados, IA e dispositivos médicos a serviço da atenção primária.', 'Dois dias de palestras e apresentações de trabalhos sobre triagem, prontuário eletrônico, telessaúde e dispositivos de baixo custo.', '[{"id":"s1","name":"Amanda Costa","role":"Pesquisadora em saúde digital","avatar":"https://randomuser.me/api/portraits/women/79.jpg"},{"id":"s2","name":"Rafaela Cunha","role":"Engenheira biomédica","avatar":"https://randomuser.me/api/portraits/women/2.jpg"}]'::jsonb, '[{"time":"09:00","title":"Conferência de abertura"},{"time":"11:00","title":"Sessão de pôsteres"},{"time":"14:00","title":"Mesa: IA na atenção primária"}]'::jsonb, 178, 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=1200&auto=format&fit=crop&q=80')
