insert into public.posts (id, author_id, is_sample, category, content, related_project_id, related_event_id, likes_base, images, created_at) values
('a1e9d51b-16ce-45fe-af47-90599073421f', '2fac2abc-9a3b-46e4-a1e3-b464672e5edb', true, 'Visão Computacional', 'Primeira saída de campo do Calçada Acessível! Passamos a manhã fotografando calçadas no centro de Niterói com 20 voluntários. O modelo já reconhece rampas quebradas e buracos com boa precisão. Próximo passo: levar o mapa para a prefeitura.', '91dd2365-3814-4314-b6e6-336d8260b6b9', null, 48, array['https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1483729558449-99ef09a8c325?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1580894894513-541e068a3e2b?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '2 hours'),
('c57b4286-2eb8-4bfe-a113-f7201985dabd', '172a49ad-6666-456e-bc8e-1b53a0ac8d82', true, 'Pesquisa Acadêmica', 'Seis meses depois da instalação, a escola rural de Cachoeiras de Macacu não ficou um dia sem aula por falta de energia. Os dados de telemetria estão abertos no repositório do projeto. Obrigado a toda a comunidade que ajudou no mutirão!', 'd2bd89e0-bb79-46c7-a7fc-e31ad55bdb57', null, 132, array['https://images.unsplash.com/photo-1509391366360-2e959784a276?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497435334941-8c899ee9e8e9?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '4 hours'),
('3991620e-c64a-43ab-9551-3c596ad1b861', '393635d7-470b-4b3a-b0ea-337e77cf0acb', true, 'Palestra Oficial', 'Inscrições abertas para o Hackathon Cidades Resilientes! 36 horas, bases de dados da cidade do Rio e mentoria de pesquisadores. Equipes de até cinco pessoas, de qualquer curso.', null, '7071b30e-d7ab-4133-b67d-ffed472e1ce9', 87, array['https://images.unsplash.com/photo-1576267423445-b2e0074d68a4?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1531545514256-b1400bc00f31?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '6 hours'),
('65fe9d05-113d-43fd-8693-c25d09d74b1a', '289474a5-0c3e-45d4-acbf-1836132b55c8', true, 'Pesquisa Acadêmica', 'Voltando do campo com 60 colônias de jataí amostradas. Agora começa a parte de laboratório: extração de DNA e preparação das bibliotecas. Abelhas sem ferrão são incríveis e merecem mais pesquisa no Brasil.', 'bda20212-a9a6-4108-8ab2-b4df9bc20e0e', null, 76, array['https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1532187863486-abf9dbad1b69?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1576086213369-97a306d36557?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '9 hours'),
('114e9942-78f7-4621-a768-455e6c937197', '57754daa-a64c-44ab-8d95-5efcce993eff', true, 'Engenharia de Software', 'O robô de monitoramento fez a primeira volta completa na fazenda experimental sem intervenção humana. 1,2 hectare mapeado em uma hora. Vídeo e código no perfil do projeto.', 'b5185655-111c-4493-ba6c-82b49057ed40', null, 154, array['https://images.unsplash.com/photo-1485827404703-89b55fcc595e?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '12 hours'),
('f83a1828-2df6-4b51-b617-1770ddfc3118', 'd9494093-240c-4b13-b115-28271d63f1aa', true, 'Pesquisa Acadêmica', 'Testamos o leitor de cardápios com 18 pessoas cegas e com baixa visão. A maior lição: menos botões, mais atalhos por voz. Vem aí a versão 2, muito mais simples.', '90c1610f-e61b-4360-b0c6-aad6f7f5f1ed', null, 98, array['https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1491438590914-bc09fcaaf77a?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '20 hours'),
('edb4663b-7307-4add-b1f5-bd288085cab6', 'b0366af0-b5c5-43b8-a5cd-f699a49fbca5', true, 'Palestra Oficial', 'Inscrições abertas para o Torneio Universitário de Robótica Autônoma! Três modalidades: navegação, manipulação e futebol de robôs. Equipes estreantes ganham mentoria antes do torneio.', null, '0b753185-8886-4384-8715-150aa7843f05', 121, array['https://images.unsplash.com/photo-1527430253228-e93688616381?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1561144257-e32e8efc6c4f?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '26 hours'),
('d766d9db-c5a8-4c49-bd48-2d180b3cf842', '94cbc1f9-eb7b-46e9-89e5-59353263f6cb', true, 'Dados e Análise', 'Analisando 40 mil projetos de lei: o tema que mais cresceu na última legislatura foi segurança pública, seguido por proteção de dados. Os gráficos completos estão na tese, capítulo 4.', 'ab428a53-7949-434a-ba83-d09511ba13b6', null, 143, array['https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1507842217343-583bb7270b66?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '30 hours'),
('9f7d0cf0-e854-4f05-acb5-1c120c050d7a', '18e94949-9ebf-44f6-8059-f8cd53407257', true, 'Engenharia de Software', 'Nosso detector de intrusão pegou 1.240 tentativas de ataque em um mês de piloto na rede do instituto. Quase todas eram varreduras automáticas, mas três eram ataques direcionados.', '9daf121b-21ba-4cd6-8f4f-fbde3f024fbf', null, 89, array['https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544197150-b99a580bb7a8?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '34 hours'),
('ce555135-4fae-47db-baa1-aa848d06c379', 'a9c3bf98-3471-46b2-9885-1c4686939cd6', true, 'Pesquisa Acadêmica', 'Peças impressas com fibra de bananeira aprovadas nos ensaios! 22% mais rígidas que o PLA puro. Elas já estão no carro Baja da equipe para a competição de dezembro.', 'cd6bf8a2-4117-4b1b-8390-5c0c453c3188', null, 67, array['https://images.unsplash.com/photo-1559136555-9303baea8ebd?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1581092160562-40aa08e78837?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '40 hours'),
('3b1226a8-0b47-4beb-a972-900afc439c5a', '9957057d-3356-4b77-903f-cef8a023c985', true, 'Engenharia de Software', '23 comércios do Méier e de Madureira já recebem pedidos pelo nosso app, sem taxa nenhuma. A padaria do Seu Antônio dobrou as vendas de fim de semana.', '736ea0c7-8c24-4df6-858f-0c4df36743ec', null, 112, array['https://images.unsplash.com/photo-1563986768609-322da13575f3?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1556761175-b413da4baf72?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '46 hours'),
('94ee8c6f-bd6e-44be-9809-bbbb29fe0f1f', '2636a1ce-1aa9-45f5-983e-4396fbcf7d42', true, 'Pesquisa Acadêmica', 'Apresentei hoje o painel de risco cardiovascular para a equipe de saúde da família. Os agentes já sugeriram três melhorias. Pesquisa boa é a que sai do papel e chega na ponta.', '4b6fdc20-6a4f-478d-b9ba-a9c01d73dc09', null, 95, array['https://images.unsplash.com/photo-1576091160550-2173dba999ef?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '52 hours'),
('54d995ae-f8bf-4471-91e8-5e15d99b5253', '83542116-501c-4021-86e8-650404dbb0eb', true, 'Dados e Análise', 'Cinco anos de imagens de satélite mostram que a turbidez da Baía de Guanabara aumenta até 40% depois de chuvas fortes. Agora estamos instalando boias com pescadores de São Gonçalo para validar.', 'bbe03ece-79bf-43bc-8d3a-f72fb1d5582c', null, 168, array['https://images.unsplash.com/photo-1483729558449-99ef09a8c325?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544989164-31dc3c645987?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '60 hours'),
('3a585bc5-39fe-4007-9907-728a2a6e2058', 'a7a9e886-eb75-4538-a10f-d9e9bc140d6e', true, 'Pesquisa Acadêmica', 'Resultado do jogo de educação financeira em 4 escolas públicas: melhora de 34% no teste de conhecimentos. E o melhor: os estudantes pediram para continuar jogando depois da aula.', '4a6bcdd3-3e90-4f94-b774-80567983387e', null, 104, array['https://images.unsplash.com/photo-1522202176988-66273c2fd55f?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '72 hours'),
('567bbf55-bd29-4b73-99e0-4327b680e98b', '8ce2c943-6f2c-4ec8-830c-9c2a135042c0', true, 'Pesquisa Acadêmica', 'Nosso CubeSat subiu 31 km num balão estratosférico e mandou 98% dos pacotes de telemetria. Próxima parada: órbita!', '7560c75c-c48f-49f9-b92d-3ec5a1f9a337', null, 211, array['https://images.unsplash.com/photo-1507413245164-6160d8298b31?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '80 hours'),
('d850ae62-a202-4c21-ad55-2b8daa65bc62', '2fac2abc-9a3b-46e4-a1e3-b464672e5edb', true, 'Pesquisa Acadêmica', 'Fechando o semestre com o redesign do aplicativo de matrícula. Nos testes, o tempo para montar a grade caiu pela metade. Obrigada a todo mundo que respondeu a pesquisa!', 'a5a6f7c9-0e2e-4e0a-a14f-d52bbb1140f1', null, 73, array['https://images.unsplash.com/photo-1559028012-481c04fa702d?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1552664730-d307ca884978?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '96 hours'),
('4e60c288-d4cb-417c-aca8-aeb32e2f9efd', '47934575-4f47-4fc8-b053-6fcdb2264f02', true, 'Pesquisa Acadêmica', 'Estudo com 300 pessoas: explicações contrafactuais curtas ("se sua renda fosse X, o crédito seria aprovado") foram as mais compreendidas. Transparência também é design.', '329dd6e8-4ba6-4b16-947f-65596394fcee', null, 126, array['https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1515879218367-8466d910aaa4?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '110 hours'),
('70f0b6fa-52ed-4e7c-b8dc-e63ce1367f13', '94a14572-afcd-4027-b9fa-7049195a5982', true, 'Pesquisa Acadêmica', 'Três pacientes testaram nossa prótese de mão por um mês. O feedback mais emocionante: "consegui segurar o copo do meu filho". Custo de materiais: R$ 780.', '3a51af2d-54f2-4355-8ebb-5b5e48fa06fd', null, 298, array['https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1559136555-9303baea8ebd?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1581092918056-0c4c3acd3789?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '130 hours'),
('e06f23ab-fcad-4304-9d67-28bca6ef6809', '90966322-bba1-4400-b809-1b16905ae78a', true, 'Dados e Análise', 'Fechamos 120 horas de fala transcrita com moradores de Itaquera, Capão Redondo e Brasilândia. O reconhecedor ajustado com esse corpus errou 37% menos. Sotaque não é ruído.', '8bd284f4-b57e-4636-9207-9d27aa0e2b9a', null, 117, array['https://images.unsplash.com/photo-1475721027785-f74eccf877e2?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1529070538774-1843cb3265df?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '150 hours'),
('bdb2cf3c-3f7a-481d-bb58-889d33f8ec95', 'c0a36741-1e20-407e-b205-53aa6bb1c037', true, 'Visão Computacional', 'Primeiros voos de drone nas lavouras de arroz em Camaquã. O classificador roda direto no celular do produtor, sem internet.', 'ab352e9f-709a-420a-a6c0-4b73fa069d9c', null, 58, array['https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1464226184884-fa280b87c399?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '170 hours'),
('cca77e9d-08f4-41a1-b5c8-bceb1057343d', 'c21bb9e1-f8a7-47cf-84f2-109835f3ee13', true, 'Palestra Oficial', 'Lembrete: a palestra "RAG e LLMs: aplicações e desafios na pesquisa acadêmica" acontece dia 26 de novembro, no auditório do Instituto de Computação. Vagas limitadas.', null, '8412e4bb-41c9-472e-a264-5f7aec515870', 64, array['https://images.unsplash.com/photo-1505373877841-8d25f7d46678?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '190 hours'),
('b9aa67ae-d71b-4df3-b1ac-51552956cbb2', '51fb2caf-babc-44fb-9356-9eda8b35cbff', true, 'Pesquisa Acadêmica', 'Blocos de concreto com 420 kg de resíduo reaproveitado por metro cúbico, atendendo à norma e 18% mais baratos. Habitação social pode e deve ser sustentável.', '8c65d7e8-03c9-4bd0-94ad-3602c69f4ba4', null, 52, array['https://images.unsplash.com/photo-1581092160562-40aa08e78837?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1528605248644-14dd04022da1?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '210 hours'),
('09b26a1a-fd20-4c38-925c-fed661a23436', '068d5593-06cd-4879-92af-15ce47ca44cc', true, 'Dados e Análise', 'Reescrevemos o código de simulação de plasma em Julia com CUDA e ficou 40 vezes mais rápido. 200 milhões de partículas numa única GPU.', '518bc18f-6f0f-4859-9f0f-8545443f7b15', null, 81, array['https://images.unsplash.com/photo-1507413245164-6160d8298b31?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1564325724739-bae0bd08762c?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '240 hours'),
('b2f78459-0161-4c45-882a-b3699325a28e', '1d32a14e-bbef-468b-8a47-da3bfa92f222', true, 'Dados e Análise', 'Nova rota da coleta seletiva entrou em teste: 23% menos quilômetros e seis bairros que nunca tiveram coleta agora vão ter.', '833fe809-2030-4d1e-ba64-7b4c485ed912', null, 47, array['https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '270 hours'),
('1cd83dfa-ec40-4b57-a037-404e28b27e96', 'c6dc2a1d-5e6b-4304-8b8a-dc9cee4efc11', true, 'Pesquisa Acadêmica', 'Oficina participativa na Praça Raul Soares com 30 moradoras. O mapa coletivo mostra que a iluminação é só parte do problema: falta movimento e comércio aberto à noite.', 'a3aa8646-2e31-4024-8c72-3b0f9ea8152d', null, 91, array['https://images.unsplash.com/photo-1528605248644-14dd04022da1?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '300 hours'),
('eea531e7-b8e1-41b9-ab83-629bf34eb903', 'b0366af0-b5c5-43b8-a5cd-f699a49fbca5', true, 'Palestra Oficial', 'O kit de sensores abertos já foi usado por 40 equipes em três hackathons. Tudo documentado e livre para qualquer universidade usar.', '7f579224-afba-462f-ad9d-373fc8b90740', null, 73, array['https://images.unsplash.com/photo-1576267423445-b2e0074d68a4?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '330 hours'),
('3a1ea33d-ac0b-465a-bf85-f94be73c3055', '18e94949-9ebf-44f6-8059-f8cd53407257', true, 'Palestra Oficial', 'O CTF Universitário do Sul está chegando! Desafios de web, cripto, reversa e forense. Inscrições gratuitas, equipes de até quatro pessoas.', null, 'b29e721a-faf1-4a02-96a2-4d7fbb52c95f', 66, array['https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '360 hours'),
('aaef9692-37cf-4a00-9f2f-699e36b2552d', '47934575-4f47-4fc8-b053-6fcdb2264f02', true, 'Palestra Oficial', 'Semana de IA da UFSC confirmada de 1 a 5 de dezembro, com mesa sobre regulação de IA no Brasil e sessão de pôsteres de IC. Mandem seus trabalhos!', null, '85e94375-d8fe-4f4e-ad42-f52d72bf09a8', 102, array['https://images.unsplash.com/photo-1519452635265-7b1fbfd1e4e0?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544531586-fde5298cdd40?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '400 hours'),
('24f026bd-748b-4f14-8567-49b73380fc13', '2fac2abc-9a3b-46e4-a1e3-b464672e5edb', true, 'Engenharia de Software', 'O guia em realidade aumentada do campus foi usado por 340 calouros na semana de recepção. Ninguém mais perdido procurando o bloco D!', 'e635a45e-0413-4f28-9129-905a6cf1ff01', null, 88, array['https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1562774053-701939374585?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '430 hours'),
('5d1c0955-3b42-4f02-8908-fa7605a45346', 'a7a9e886-eb75-4538-a10f-d9e9bc140d6e', true, 'Palestra Oficial', 'Feira de Startups Universitárias no Ibmec em 10 de dezembro. Mais de 30 startups, rodada de pitches e mentoria com investidores. Bora?', null, 'b4bed9a3-d853-42bf-be7c-c4d38809f385', 77, array['https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1559223607-a43c990c692c?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '460 hours'),
('9c84699d-a449-4cb4-912f-dfae15cbb22f', '172a49ad-6666-456e-bc8e-1b53a0ac8d82', true, 'Palestra Oficial', 'Vou apresentar a microrrede solar no Seminário de Transição Energética, online, dia 3 de dezembro. Quem quiser assistir, o link está no evento.', null, 'e79457de-1544-4595-a67f-91f02e6f07f4', 41, array['https://images.unsplash.com/photo-1466611653911-95081537e5b7?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '500 hours'),
('95a5092b-fe03-44e9-b304-1e92398abfa8', '5a885de2-e187-4ab4-8fba-cdcd355142b5', true, 'Visão Computacional', 'Treino de sábado no laboratório. A CapyVision agora roda a 120 quadros por segundo com o novo rastreador.', 'b8d640a9-2ac8-463d-b71b-524c4030527e', null, 59, array['https://images.unsplash.com/photo-1561144257-e32e8efc6c4f?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1485827404703-89b55fcc595e?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '540 hours'),
('45a1296f-2550-4cd5-88c8-add5ca84f729', '07ccd120-1caf-4c08-8f99-631ae11f170d', true, 'Dados e Análise', 'Fechei a avaliação da arquitetura RAG com 2 mil perguntas sobre teses brasileiras. As citações agora apontam para o parágrafo exato da fonte.', '442306d0-c2fb-437b-88f9-c19f54854605', null, 93, array['https://images.unsplash.com/photo-1481627834876-b7833e8f5570?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1488590528505-98d2b5aba04b?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '600 hours'),
('8800597b-a207-4634-8d32-de41456a0233', '23929862-501c-4488-8cb3-392a5f284efc', true, 'Pesquisa Acadêmica', 'Mais 40 moléculas da biodiversidade brasileira entraram na triagem virtual. Duas mostraram afinidade promissora com o alvo. Agora é validar em bancada.', '6082a412-5e2c-4152-aea8-2a8b5c3046ab', null, 71, array['https://images.unsplash.com/photo-1532094349884-543bc11b234d?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1518152006812-edab29b069ac?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '650 hours'),
('40c4ae40-8df4-4eec-bce0-141c2be841b1', '03f897a3-2f3d-4314-bd11-e19cfb387623', true, 'Dados e Análise', 'Os mapas de qualidade do ar agora atualizam de hora em hora. Teste no seu bairro e me conta se faz sentido com o que você sente na rua.', '3e7c8fc8-171b-4514-9686-83a230a95a1b', null, 84, array['https://images.unsplash.com/photo-1526778548025-fa2f459cd5c1?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '700 hours'),
('2eb0057c-faa4-435e-9885-7a8a3bf1f326', 'fa02873d-5b68-49f4-8a23-819e8ad37d10', true, 'Pesquisa Acadêmica', 'O SabiáEdu passou de mil textos revisados! Os comentários mais comuns: parágrafos longos demais e referências sem padrão. Clássico.', '0e0fb633-def2-4e05-ad05-b8ce24c74a6b', null, 62, array['https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '760 hours'),
('99ad0bae-f993-4e87-b245-a7a8f10c68ce', '4fc6858c-87d0-4400-8673-e183eb4405c3', true, 'Engenharia de Software', 'Integramos LLMs no fluxo de triagem de chamados da equipe e o tempo de primeira resposta caiu bastante. Escrevi um resumo do que funcionou e do que não funcionou.', '90fba419-43f3-4f5a-9063-b354a0f79001', null, 55, array['https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '820 hours'),
('524c34b7-d6b6-4ec4-8903-3fcd97998d91', '8ce2c943-6f2c-4ec8-830c-9c2a135042c0', true, 'Palestra Oficial', 'Obrigado a todos que foram na Jornada de Engenharia Aeroespacial! Os slides e a gravação estão na página do evento.', null, 'b0e1bfa3-dadd-4989-81b8-856c776f3c08', 96, array['https://images.unsplash.com/photo-1505373877841-8d25f7d46678?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544531586-fde5298cdd40?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '900 hours'),
('b06dd6aa-53a1-4374-a767-ea0cac45a10c', '2636a1ce-1aa9-45f5-983e-4396fbcf7d42', true, 'Palestra Oficial', 'Submissões abertas para o Simpósio de Saúde Digital da UERJ, em fevereiro. Trabalhos de graduação são muito bem-vindos.', null, '64799a83-0d20-400a-8567-c0b5adf49bfe', 58, array['https://images.unsplash.com/photo-1579154204601-01588f351e67?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1530497610245-94d3c16cda28?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '950 hours'),
('00ea4af7-0811-46a0-b60c-87fa74d4151e', '289474a5-0c3e-45d4-acbf-1836132b55c8', true, 'Palestra Oficial', 'A Escola de Verão em Bioinformática da USP abriu inscrições. Uma semana de aulas práticas, com bolsas de hospedagem para quem vem de fora.', null, '04cd64b1-9f88-4988-a06c-63be92e79192', 69, array['https://images.unsplash.com/photo-1518152006812-edab29b069ac?w=1200&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1532187863486-abf9dbad1b69?w=1200&auto=format&fit=crop&q=80']::text[], now() - interval '1000 hours')
on conflict (id) do nothing;

insert into public.comments (id, post_id, author_id, text, created_at) values
('9ddfc40c-af06-40ca-a48c-491450acff17', 'a1e9d51b-16ce-45fe-af47-90599073421f', 'd9494093-240c-4b13-b115-28271d63f1aa', 'Que manhã boa! As fotos das rampas ficaram ótimas para o conjunto de treino.', now() - interval '2 hours' + interval '17 minutes'),
('8b0a7fb9-f070-4309-b580-10f1e5bcbb9f', 'a1e9d51b-16ce-45fe-af47-90599073421f', 'b6f3063e-e60e-49f5-bd47-2e551099e279', 'Se precisarem cruzar com dados de relevo, me chama. Tenho as camadas de Niterói prontas.', now() - interval '2 hours' + interval '34 minutes'),
('d29c00ed-3b38-4713-afd4-b3296e6adab1', 'a1e9d51b-16ce-45fe-af47-90599073421f', 'c6dc2a1d-5e6b-4304-8b8a-dc9cee4efc11', 'Isso conversa muito com o meu TCC em BH. Bora trocar uma ideia?', now() - interval '2 hours' + interval '51 minutes'),
('7cc0f784-213e-4ad8-aeeb-be98dfb477f7', 'c57b4286-2eb8-4bfe-a113-f7201985dabd', '83542116-501c-4021-86e8-650404dbb0eb', 'Que resultado incrível, Lucas!', now() - interval '4 hours' + interval '17 minutes'),
('a3a2dc87-2ba0-4168-b541-794d06cee096', 'c57b4286-2eb8-4bfe-a113-f7201985dabd', '8ce2c943-6f2c-4ec8-830c-9c2a135042c0', 'Qual rádio vocês usaram na telemetria? LoRa funcionou bem com a vegetação?', now() - interval '4 hours' + interval '34 minutes'),
('06c5e0b1-ca7d-483b-b9d7-0b18bb95f2fb', 'c57b4286-2eb8-4bfe-a113-f7201985dabd', '172a49ad-6666-456e-bc8e-1b53a0ac8d82', 'LoRa a 915 MHz com antena externa. Chegou a 6 km sem problemas.', now() - interval '4 hours' + interval '51 minutes'),
('d9ce249b-c974-47ee-b3fe-a03d9fae0dc1', '3991620e-c64a-43ab-9551-3c596ad1b861', '9957057d-3356-4b77-903f-cef8a023c985', 'Já montei equipe com o pessoal do CEFET!', now() - interval '6 hours' + interval '17 minutes'),
('cfe5ad62-e8c2-488b-9a29-87eac3874260', '3991620e-c64a-43ab-9551-3c596ad1b861', '2fac2abc-9a3b-46e4-a1e3-b464672e5edb', 'Alguém de design procurando equipe? Tô dentro.', now() - interval '6 hours' + interval '34 minutes'),
('2201ba27-c62e-4ce0-ba5a-8dd32769ed09', '65fe9d05-113d-43fd-8693-c25d09d74b1a', '23929862-501c-4488-8cb3-392a5f284efc', 'Que trabalho bonito, Camila. Vocês vão disponibilizar os dados brutos?', now() - interval '9 hours' + interval '17 minutes'),
('72ff5540-2929-4383-a259-cceed6e34f44', '65fe9d05-113d-43fd-8693-c25d09d74b1a', '289474a5-0c3e-45d4-acbf-1836132b55c8', 'Sim! Tudo vai para o SRA quando o artigo sair.', now() - interval '9 hours' + interval '34 minutes'),
('b70e7b4e-d0ce-41a8-9a84-4e4eab5562b7', '114e9942-78f7-4621-a768-455e6c937197', 'c0a36741-1e20-407e-b205-53aa6bb1c037', 'Agora falta testar na lavoura de arroz lá do sul!', now() - interval '12 hours' + interval '17 minutes'),
('9b19aaac-73a1-447e-b399-da22daf3e2c0', '114e9942-78f7-4621-a768-455e6c937197', '5a885de2-e187-4ab4-8fba-cdcd355142b5', 'Que estabilidade na navegação. Vocês estão usando Nav2 puro?', now() - interval '12 hours' + interval '34 minutes'),
('698a4096-cfb2-4608-8fa9-24e12e7ad554', '114e9942-78f7-4621-a768-455e6c937197', '57754daa-a64c-44ab-8d95-5efcce993eff', 'Nav2 com um planejador próprio para seguir as linhas de plantio.', now() - interval '12 hours' + interval '51 minutes'),
