('5902e6ee-a65f-460c-b1c6-12c75149ca7f', 'f83a1828-2df6-4b51-b617-1770ddfc3118', '2636a1ce-1aa9-45f5-983e-4396fbcf7d42', 'Vocês pensaram em levar para farmácias e bulas também?', now() - interval '20 hours' + interval '34 minutes'),
('a60955a7-f4dc-40ea-a972-fea5a1492c6b', 'edb4663b-7307-4add-b1f5-bd288085cab6', '57754daa-a64c-44ab-8d95-5efcce993eff', 'Equipe da casa confirmada!', now() - interval '26 hours' + interval '17 minutes'),
('f1a37bab-cfca-471f-affd-7b39702f3723', 'edb4663b-7307-4add-b1f5-bd288085cab6', '5a885de2-e187-4ab4-8fba-cdcd355142b5', 'A CapyVision vai com tudo esse ano.', now() - interval '26 hours' + interval '34 minutes'),
('1f38e33b-6237-4ef2-8964-99f6e3b36f59', 'd766d9db-c5a8-4c49-bd48-2d180b3cf842', '47934575-4f47-4fc8-b053-6fcdb2264f02', 'Você testou se o modelo trata bem propostas com texto muito curto?', now() - interval '30 hours' + interval '17 minutes'),
('01763120-e1c3-46c6-a48c-9d1d1f22a42d', 'd766d9db-c5a8-4c49-bd48-2d180b3cf842', '94cbc1f9-eb7b-46e9-89e5-59353263f6cb', 'Boa pergunta. Abaixo de 50 palavras o F1 cai para 0,78. Está nas limitações.', now() - interval '30 hours' + interval '34 minutes'),
('3a3bfccf-ee8a-4c1e-91d5-b935712a88ad', '9f7d0cf0-e854-4f05-acb5-1c120c050d7a', '068d5593-06cd-4879-92af-15ce47ca44cc', 'Assustador e fascinante ao mesmo tempo.', now() - interval '34 hours' + interval '17 minutes'),
('3faa52f1-b805-46e2-9041-43ace25eda0e', 'ce555135-4fae-47db-baa1-aa848d06c379', '51fb2caf-babc-44fb-9356-9eda8b35cbff', 'Que ideia boa usar resíduo agrícola.', now() - interval '40 hours' + interval '17 minutes'),
