('86fde67f-69cd-4c4a-904c-ef745acaffc9', '3b1226a8-0b47-4beb-a972-900afc439c5a', 'a7a9e886-eb75-4538-a10f-d9e9bc140d6e', 'Orgulho desse projeto!', now() - interval '46 hours' + interval '17 minutes'),
('aa2f543e-37d2-4695-beca-ca5384161a17', '3b1226a8-0b47-4beb-a972-900afc439c5a', '2fac2abc-9a3b-46e4-a1e3-b464672e5edb', 'Que história boa. Manda um abraço para o Seu Antônio.', now() - interval '46 hours' + interval '34 minutes'),
('ee58102f-bcf4-4ca6-a359-59dacbd94f81', '94ee8c6f-bd6e-44be-9809-bbbb29fe0f1f', '94a14572-afcd-4027-b9fa-7049195a5982', 'Arrasou, Amanda!', now() - interval '52 hours' + interval '17 minutes'),
('08c26ef2-6305-456a-809c-b66c43fbb56b', '54d995ae-f8bf-4471-91e8-5e15d99b5253', 'b6f3063e-e60e-49f5-bd47-2e551099e279', 'Esse cruzamento com as estações do ar ficou muito bom.', now() - interval '60 hours' + interval '17 minutes'),
('b5056354-919e-4993-a8a7-d42450031343', '54d995ae-f8bf-4471-91e8-5e15d99b5253', '172a49ad-6666-456e-bc8e-1b53a0ac8d82', 'Se precisarem de energia solar para as boias, estamos aqui.', now() - interval '60 hours' + interval '34 minutes'),
('e58d5b6c-8ab2-4724-aa96-185b564ce72d', '54d995ae-f8bf-4471-91e8-5e15d99b5253', '83542116-501c-4021-86e8-650404dbb0eb', 'Vou te chamar, Lucas!', now() - interval '60 hours' + interval '51 minutes'),
('a343c183-fc4d-45c7-b11f-bf8d1e370267', '3a585bc5-39fe-4007-9907-728a2a6e2058', '90966322-bba1-4400-b809-1b16905ae78a', 'Que lindo ver isso funcionando em sala.', now() - interval '72 hours' + interval '17 minutes'),
('3e65d7bd-fe1e-4d29-adb9-3356a79c22ba', '567bbf55-bd29-4b73-99e0-4327b680e98b', '068d5593-06cd-4879-92af-15ce47ca44cc', 'Que foto da curvatura da Terra!', now() - interval '80 hours' + interval '17 minutes'),
