('906921ac-d066-4282-b756-7aa6991c9e08', '567bbf55-bd29-4b73-99e0-4327b680e98b', '2fac2abc-9a3b-46e4-a1e3-b464672e5edb', 'Arrepiei aqui.', now() - interval '80 hours' + interval '51 minutes'),
