('0a973fed-8d0f-4b27-8324-4fdc9ad21f69', '4e60c288-d4cb-417c-aca8-aeb32e2f9efd', '94cbc1f9-eb7b-46e9-89e5-59353263f6cb', 'Isso deveria virar recomendação regulatória.', now() - interval '110 hours' + interval '17 minutes'),
