('c66efb98-1698-4f59-97dd-baf44cf2450b', 'e06f23ab-fcad-4304-9d67-28bca6ef6809', '94cbc1f9-eb7b-46e9-89e5-59353263f6cb', 'Vocês pretendem abrir o corpus?', now() - interval '150 hours' + interval '17 minutes'),
