insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
  created_at, updated_at, confirmation_token, recovery_token, email_change, email_change_token_new, email_change_token_current)
select '00000000-0000-0000-0000-000000000000', 'bb893db0-ca01-42c6-a898-330a3f003688', 'authenticated', 'authenticated', 'demo@capyfolio.test',
  extensions.crypt('capyfolio-demo', extensions.gen_salt('bf')), now(),
  '{"provider":"email","providers":["email"],"demo":true}'::jsonb, '{"name":"Júlia Andrade"}'::jsonb,
  now(), now(), '', '', '', '', ''
where not exists (select 1 from auth.users where email = 'demo@capyfolio.test');

