select gen_random_uuid(), 'bb893db0-ca01-42c6-a898-330a3f003688', 'bb893db0-ca01-42c6-a898-330a3f003688', 'email',
  jsonb_build_object('sub', 'bb893db0-ca01-42c6-a898-330a3f003688', 'email', 'demo@capyfolio.test', 'email_verified', true), now(), now(), now()
where not exists (select 1 from auth.identities where user_id = 'bb893db0-ca01-42c6-a898-330a3f003688');

